(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.035-t*0.5)*8+Math.cos((y+w1y)*0.025+t*0.4)*6;
  const w2y = Math.cos((y+w1y)*0.03+t*0.45)*8+Math.sin((x+w1x)*0.028-t*0.55)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [60+Math.sin(t*0.45+3)*70,100+Math.cos(t*0.65+2)*60,0.11,2.1],
    [400+Math.cos(t*0.55+1)*60,220+Math.sin(t*0.75+4)*50,0.05,2.8],
    [200+Math.sin(t*0.38+6)*110,30+Math.cos(t*0.58+3)*40,0.13,1.3]
  ];
  let aS=0,iS=0,mS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w=Math.sin(d*f-t*sp);
    aS+=w; iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    mS+=Math.sin(d*f*1.4-t*sp*0.4+2.8)*0.5;
  }
  const act=aS/9,inh=iS/9,mod=mS/9;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2=(Math.sin(dist*0.08+ang*2-t*2.2)+Math.cos(dist*0.06-ang*5+t*1.8))*0.2;
  const voronoi=()=>{let md=99;for(let i=0;i<src.length;i++){const dx=sx-src[i][0],dy=sy-src[i][1];const d=Math.sqrt(dx*dx+dy*dy);if(d<md)md=d;}return md;};
  const vEdge=1.0/(1.0+voronoi()*0.15);
  const rd1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const rd2=Math.tanh((mod*0.6-inh*0.4+spiral2+bg*0.2)*2.8);
  const cross=Math.sin(rd1*3.14)*Math.sin(rd2*3.14+t*0.5);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=Math.sin(sx*0.4+t*3)*Math.sin(sy*0.4-t*2.5)*0.08;
  const blend=rd1*0.45+rd2*0.25+cross*0.15+cell*0.1+micro;
  const v=blend*0.5+0.5;
  const hShift=Math.sin(t*0.15)*0.5+0.5;
  const pal=[
    [5,12,55],[12,45,95],[18,90,120],[25,140,135],
    [60,170,120],[150,185,75],[210,175,55],
    [220,130,60],[195,80,65],[150,45,70],[90,25,60],[40,15,50],[5,12,55]
  ];
  const off=hShift*(pal.length-1);
  const shifted=(v*(pal.length-1)+off)%(pal.length-1);
  const idx=shifted,i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.75+Math.sin(rd1*Math.PI)*0.15+Math.sin(rd2*Math.PI)*0.1;
  const edge=(Math.abs(rd1)>0.65||Math.abs(rd2)>0.65)?1.2:1.0;
  const vGlow=vEdge*0.12;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+vGlow*30)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+vGlow*50)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+vGlow*80)|0)
  ];
}
